async function loadUsers() {
  const response = await fetch("https://api.example.com/users");
  if (!response.ok) {
    throw new Error(`Request failed with status ${response.status}`);
  }
  const users = await response.json();   // parses the JSON body
  for (const user of users) {
    console.log(`${user.name} (${user.email})`);
  }
}

loadUsers().catch((error) => console.log(error.message));

// A Response like the one fetch() would resolve with, built locally
const fake = new Response('[{"name":"Ada"},{"name":"Grace"}]', {
  status: 200,
  headers: { "Content-Type": "application/json" },
});

async function show(response) {
  console.log(response.ok);
  console.log(response.status);
  console.log(response.headers.get("content-type"));
  const data = await response.json();
  console.log(data.map((u) => u.name).join(", "));
}

show(fake);

async function createTodo(title) {
  const response = await fetch("https://api.example.com/todos", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ title, done: false }),
  });
  if (!response.ok) throw new Error(`Could not save: ${response.status}`);
  return response.json();
}

createTodo("Learn fetch").then((created) => console.log(created.id));
